import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Pull requests","description":"Feature-branch PRs: Conventional Commits title, a linked Issue is mandatory, the version and changelog follow automatically, keep OpenAPI in sync, never hand-edit generated clients.","frontmatter":{"title":"Pull requests","description":"Feature-branch PRs: Conventional Commits title, a linked Issue is mandatory, the version and changelog follow automatically, keep OpenAPI in sync, never hand-edit generated clients."},"headers":[],"relativePath":"en/contribute/pull-requests.md","filePath":"en/contribute/pull-requests.md","lastUpdated":1790057721000}`),a={name:`en/contribute/pull-requests.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="pull-requests" tabindex="-1">Pull requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to “Pull requests”">​</a></h1><p>Branch from the default branch and open a PR against <a href="https://github.com/Kirizu-Official/KiriVers" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers</a>.</p><h2 id="the-pr-title-is-where-the-version-comes-from" tabindex="-1">The PR title is where the version comes from <a class="header-anchor" href="#the-pr-title-is-where-the-version-comes-from" aria-label="Permalink to “The PR title is where the version comes from”">​</a></h2><p>The squash commit message of a merge into <code>main</code> is taken from the PR title, and that title decides whether the merge bumps a version:</p><table tabindex="0"><thead><tr><th>Type</th><th>Bump</th></tr></thead><tbody><tr><td><code>feat</code></td><td>minor</td></tr><tr><td><code>fix</code> / <code>perf</code> / <code>revert</code></td><td>patch</td></tr><tr><td><code>type!:</code> or a body <code>BREAKING CHANGE:</code></td><td>major</td></tr><tr><td><code>docs</code> / <code>refactor</code> / <code>test</code> / <code>style</code> / <code>chore</code> / <code>ci</code> / <code>build</code></td><td>no release</td></tr></tbody></table><p>Format: <code>&lt;type&gt;(&lt;optional scope&gt;): &lt;one-line summary&gt;</code>, for example <code>fix(client): 修正空响应</code>. Allowed types: feat | fix | perf | revert | docs | refactor | test | style | chore | ci | build.</p><ul><li><strong>Use a lowercase scope</strong> (<code>perf(db)</code>, not <code>perf(DB)</code>). It is also the per-entry attribution label in the changelog.</li><li>Write a breaking change as <code>type!:</code> or add a <code>BREAKING CHANGE:</code> footer to the body.</li><li>Both the PR title and every commit must conform (<code>python3 dev/build/kirivers.py commitlint</code>). A non-conforming squash title fails the check.</li></ul><h2 id="every-pr-must-link-an-issue" tabindex="-1">Every PR must link an Issue <a class="header-anchor" href="#every-pr-must-link-an-issue" aria-label="Permalink to “Every PR must link an Issue”">​</a></h2><p>Each Pull Request that lands on <code>main</code> has to reference an Issue — either way works:</p><ul><li>use the right-hand sidebar <strong>Development → Link an issue</strong>, or</li><li>write one line in the PR description: <code>Fixes #&lt;number&gt;</code> (<code>Closes</code> / <code>Resolves</code> are equally valid, any casing).</li></ul><p>When an Issue genuinely is not needed, add the <code>skip-issue-check</code> label to that PR.</p><p>Scope of the gate: <strong>only PRs targeting <code>main</code></strong>. Direct pushes to <code>main</code> (maintainers) and PRs into the <code>sdk/&lt;lang&gt;</code> branches are not gated — releasing on an SDK branch is that branch&#39;s own pipeline.</p><h3 id="what-the-guard-bot-does" tabindex="-1">What the guard bot does <a class="header-anchor" href="#what-the-guard-bot-does" aria-label="Permalink to “What the guard bot does”">​</a></h3><p><code>.github/workflows/pr-guard.yml</code> re-checks the title format and the Issue link when a PR is opened, edited, pushed to, reopened, or marked ready for review, and keeps <strong>one</strong> comment thread updated in the PR (no comment spam):</p><ul><li>An outside contributor (non-organisation member) who fails a check gets a comment and the PR is <strong>closed automatically</strong>. The branch is not deleted and the PR is not locked: once you have fixed things, click <strong>Reopen pull request</strong> and the guard re-checks and updates that same comment to a pass; you do not have to open a new PR.</li><li>An organisation member (OWNER / MEMBER / COLLABORATOR) who fails gets the comment only — no close.</li><li><strong>Draft PRs and bot authors are exempt entirely</strong> (something still in progress should not be closed). The <code>skip-issue-check</code> label exempts the Issue requirement only; the title check still applies.</li></ul><p>The guard reads PR metadata only. It never checks out or executes code that comes in with the PR, and it builds and tests nothing.</p><p>For the order — open the Issue first, then the PR bound to it — see <a href="/en/contribute/bugs">Report a bug</a>.</p><h2 id="the-changelog-is-generated-—-do-not-hand-write-it" tabindex="-1">The changelog is generated — do not hand-write it <a class="header-anchor" href="#the-changelog-is-generated-—-do-not-hand-write-it" aria-label="Permalink to “The changelog is generated — do not hand-write it”">​</a></h2><p><code>CHANGELOG.md</code> and the GitHub Release body are both generated from commits by the release scripts (format, plus the customisable emoji and labels: <a href="/en/contribute/release#changelog-format">Release and Docker</a>). Editing <code>CHANGELOG.md</code> by hand gets shoved around by the next release&#39;s header insert, and it changes no version number. Sections come from <code>type</code>, and the <code>**scope**</code> in each entry comes from your scope — get the scope right and entries file themselves.</p><h2 id="other-requirements" tabindex="-1">Other requirements <a class="header-anchor" href="#other-requirements" aria-label="Permalink to “Other requirements”">​</a></h2><ul><li>Relevant <code>go test</code> / frontend lint pass.</li><li>API changes update that plane&#39;s <code>internal/controller/openapi.*.json</code> and keep <code>TestOpenAPIRoutesSync</code> / <code>TestPlaneSpecsValid</code> green.</li><li>Frontend contract changes: run <code>yarn generate:api</code> in <code>frontend/</code>. Do not hand-edit <code>src/api/generated/</code> or <code>generated-client/</code>.</li><li>Do not push language SDK sources to <code>main</code> — they live on the orphan branches <code>sdk/&lt;lang&gt;</code>, see <a href="/en/contribute/sdk">SDK source branches</a>.</li><li>Do not commit secret-bearing <code>configs/*.yaml</code> (only <code>*-example.yaml</code>).</li><li>Merging into <code>main</code> does <strong>not</strong> publish the server: release is a workflow a maintainer runs by hand.</li></ul><h2 id="local-self-check" tabindex="-1">Local self-check <a class="header-anchor" href="#local-self-check" aria-label="Permalink to “Local self-check”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev/build/kirivers.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-workflows</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      # pipeline static gate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev/build/kirivers.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> guard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-check</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # guard decision matrix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev/build/kirivers.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> issue-link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-check</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CGO_ENABLED</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>On Windows replace <code>python3</code> with <code>python</code>.</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};